78          * REVISIT: Only USB devices for now. If there are others, these need to
79          * be converted into a list.
80          *
81          * NOTE: These may be registered first before the typec_partner, so they
82          * will always have to be kept here instead of struct typec_partner.
83          */
84         struct device                   *usb2_dev;
85         struct device                   *usb3_dev;
```
No `get_device()` is ever taken on them. They are set/cleared only here:

`drivers/usb/typec/class.c:2144-2186`
```c
2144 static void typec_partner_attach(struct typec_connector *con, struct device *dev)
2151         mutex_lock(&port->partner_link_lock);
2152         if (udev->speed < USB_SPEED_SUPER) {
2154                 port->usb2_dev = dev;        /* stored BEFORE link creation */
2157                 port->usb3_dev = dev;
2160         partner = typec_get_partner(port);
2163                 typec_partner_link_device(partner, dev);

2169 static void typec_partner_deattach(struct typec_connector *con, struct device *dev)
2177                 typec_partner_unlink_device(partner, dev);
2181         if (port->usb2_dev == dev) port->usb2_dev = NULL;
2183         else if (port->usb3_dev == dev) port->usb3_dev = NULL;
```

Two concrete defects follow:

**(a) Pointer stored even when no link was created.** `typec_partner_link_device()` bails out early on failure:
`class.c:888-904`
```c
892         ret = sysfs_create_link(&dev->kobj, &partner->dev.kobj, "typec");
893         if (ret)
894                 return;                       /* nothing created */
896         ret = sysfs_create_link(&partner->dev.kobj, &dev->kobj, dev_name(dev));
897         if (ret) {
898                 sysfs_remove_link(&dev->kobj, "typec");
899                 return;
900         }
```
but `port->usb2_dev` was already assigned at line 2154. Also, `typec_register_partner()` links only if the pointer is set (`class.c:1158-1161`) — with no record of success. Unregister then removes links that never existed.

**(b) Lifetime/ordering race (your actual boot case).** The USB device can be unregistered by USB core (hub teardown → `sysfs_remove_dir()` → `kobj->sd = NULL`) without `typec_partner_deattach()` having run for it, or before it runs. `port->usb2_dev` then dangles as a *sysfs-dead* device. `partner_link_lock` (`class.h:64`) serializes attach/deattach/register/unregister against each other, but it does **not** synchronize against USB device teardown and takes no refcount — so it cannot prevent this.

## 4. Why UCSI is the trigger, and why at boot

`drivers/usb/typec/ucsi/ucsi.c:1264-1327` (`ucsi_handle_connector_change`, the workqueue item — your `kworker/6:0`):
```c
1306         if (change & UCSI_CONSTAT_CONNECT_CHANGE) {
1309                 ucsi_partner_change(con);
1312                 if (UCSI_CONSTAT(con, CONNECTED)) {
1313                         ucsi_register_partner(con);
1324                 } else {
1325                         ucsi_unregister_partner(con);      /* <-- your path */
1326                 }
```
→ `drivers/usb/typec/ucsi/ucsi.c:1138-1154`
```c
1138 static void ucsi_unregister_partner(struct ucsi_connector *con)
1140         if (!con->partner) return;
1143         typec_set_mode(con->port, TYPEC_STATE_SAFE);
1147         typec_partner_set_usb_power_delivery(con->partner, NULL);
1148         ucsi_unregister_partner_pdos(con);
1149         ucsi_unregister_altmodes(con, UCSI_RECIPIENT_SOP);
1150         ucsi_unregister_cable(con);
1151         typec_unregister_partner(con->partner);            /* -> class.c:1174 */
1153         con->partner = NULL;
```

At boot the Dell Pro Precision 5 16's PPM reports a burst of connector-change events (Thunderbolt/USB4 retimer + internal hub coming up). A partner is registered, the USB device behind it is enumerated (`typec_partner_attach` sets `usb2_dev`/`usb3_dev`), the PPM then reports *disconnect* while the USB device is being torn down concurrently. `ucsi_unregister_partner()` runs, sees non‑NULL `port->usb2_dev`, and unlinks against an already-dead sysfs directory → `!parent` → WARN.

Note the other two callers that can do the same: `ucsi_check_connection()` (`ucsi.c:1221`) and `ucsi_unregister()` (`ucsi.c:2147`, during module/driver removal, after USB teardown).

